    string lessonId,
    ClaimsPrincipal user,
    ILessonCompletionService service,
    CancellationToken ct) =>
{
    var userId = user.RequireUserId();
    await service.CompleteLessonAsync(userId, lessonId, ct);
    return Results.Ok(new { ok = true });
});

public enum CompletionOutcome { Completed, AlreadyCompleted, LessonNotFound }

app.MapPost("/lessons/{lessonId}/complete", async (
    string lessonId, ClaimsPrincipal user, ILessonCompletionService service, CancellationToken ct) =>
{
    var outcome = await service.CompleteLessonAsync(user.RequireUserId(), lessonId, ct);

    return outcome switch
    {
        CompletionOutcome.LessonNotFound => Results.NotFound(),
        // Completing twice is not an error: the operation is idempotent.
        _ => Results.Ok(new { outcome = outcome.ToString() }),
    };
});
